    private static final Map<String,Feature> BY_ID=index();
    private static Feature f(String phase,String id,String name){return new Feature(phase,id,name);}
    private static Map<String,Feature> index(){Map<String,Feature> m=new LinkedHashMap<>();for(Feature f:FEATURES)m.put(f.id(),f);return Map.copyOf(m);}
    public static List<Feature> features(){return FEATURES;}
    public static List<Feature> features(String phase){String p=upper(phase);return FEATURES.stream().filter(v->v.phase().equals(p)).toList();}
    public static Feature feature(String id){return BY_ID.get(upper(id));}

    public static RunResult run(ServerPlayer player,String featureId,String subjectId,String input){
        ServerLevel world=player.level();Feature feature=feature(featureId);if(feature==null)throw new IllegalArgumentException("Unknown P6-P10 feature: "+featureId);
        String subject=clean(subjectId);String text=input==null?"":input.trim();
        Analysis a=analyze(world,player,feature,subject,text);
        long now=System.currentTimeMillis();var data=OceanCanvasProgramData.get(world);String id=data.newId(feature.id().substring(3).toLowerCase(Locale.ROOT));
        String author=player.getGameProfile().name();
        String label=switch(feature.id()){
            case "OC-F068","OC-F251" -> text.isBlank()?feature.name():text;
            case "OC-F278" -> {String[] f=text.split("\\|",-1);yield f.length>0&&!f[0].isBlank()?f[0]:feature.name();}
            default -> feature.name();
        };
        var entry=new OceanCanvasProgramData.Entry(id,feature.phase(),feature.id(),a.kind(),subject,label,a.x(),a.z(),a.state(),a.payload(),author,now,now);
        if("OC-F287".equals(feature.id())&&!subject.isBlank())data.setGovernanceState("freeze:"+subject,a.state());
        data.putEntry(entry);data.addEvidence(new OceanCanvasProgramData.Evidence(data.newId("evidence"),feature.phase(),feature.id(),subject,a.state(),a.severity(),a.summary(),a.x(),a.z(),now));
        if(OceanCanvasReadOnlyApi.running())OceanCanvasReadOnlyApi.publish(world);
        return new RunResult(feature.phase(),feature.id(),feature.name(),a.state(),a.severity(),a.summary(),id);
    }

