    // ----- P6 helpers -----
    private static Analysis materialDemand(List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){Map<String,Integer> demand=new LinkedHashMap<>();for(var t:tasks)for(var c:t.checklist()){String s=c.text().trim();if(!s.toUpperCase(Locale.ROOT).startsWith("MATERIAL:"))continue;String body=s.substring(9).trim();String[] f=body.split("[ xX*]",2);String key=f[0].isBlank()?"unspecified":f[0].toLowerCase(Locale.ROOT);int qty=1;if(f.length>1)try{qty=Math.max(1,Integer.parseInt(f[1].replaceAll("[^0-9]","")));}catch(Exception ignored){}if(!c.complete())demand.merge(key,qty,Integer::sum);}int total=demand.values().stream().mapToInt(Integer::intValue).sum();String top=demand.entrySet().stream().sorted(Map.Entry.<String,Integer>comparingByValue().reversed()).limit(8).map(e->e.getKey()+"="+e.getValue()).reduce((a,b)->a+", "+b).orElse("no MATERIAL: checklist tags");return new Analysis("MATERIAL_MAP",demand.isEmpty()?"UNVERIFIED":"PASS",demand.isEmpty()?35:0,"Outstanding material demand "+total+" units across "+demand.size()+" tagged material(s): "+top,top,x,z);}
    private static Analysis supplyRoutes(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){var routes=routeObjects(plan);double taskDist=tasks.stream().filter(t->!t.terminal()).mapToDouble(t->Math.hypot(t.x()-x,t.z()-z)).average().orElse(0);String mode=routes.stream().map(o->o.parsedType().name()).distinct().sorted().reduce((a,b)->a+","+b).orElse("NONE");int sev=routes.isEmpty()&&!tasks.isEmpty()?65:0;return new Analysis("ROUTE_PLAN",sev>0?"WARN":"PASS",sev,"Supply network has "+routes.size()+" planned route object(s) across "+mode+"; mean distance to unfinished project tasks "+Math.round(taskDist)+" blocks.","routes="+routes.size()+";modes="+mode+";meanTaskDistance="+Math.round(taskDist),x,z);}
    private static Analysis constructionOverlay(OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){if(p==null)return missingProject(x,z);Map<String,Long> byPhase=new LinkedHashMap<>();for(var t:tasks)byPhase.merge(t.phaseId().isBlank()?"unphased":t.phaseId(),1L,Long::sum);String active=p.phases().stream().filter(v->!v.complete()).sorted(Comparator.comparingInt(OceanCanvasWorkspaceData.ProjectPhase::order)).map(OceanCanvasWorkspaceData.ProjectPhase::name).findFirst().orElse("complete/unphased");long visible=tasks.stream().filter(t->t.phaseId().isBlank()||p.phases().stream().anyMatch(ph->ph.id().equals(t.phaseId())&&ph.name().equals(active))).count();return new Analysis("PHASE_OVERLAY","PASS",0,"Active construction overlay '"+active+"' contains "+visible+" task(s); "+byPhase.size()+" phase bucket(s) are indexed.","active="+active+";phaseBuckets="+byPhase,x,z);}
    private static Analysis punchList(OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,String input,int x,int z){long incomplete=tasks.stream().flatMap(t->t.checklist().stream()).filter(c->!c.complete()).count();long blocked=tasks.stream().filter(t->t.parsedStatus()==OceanCanvasWorkspaceData.TaskStatus.BLOCKED).count();String note=input.isBlank()?"Field capture at "+x+","+z:input;return new Analysis("PUNCH_LIST",blocked>0?"ATTENTION":"PASS",(int)Math.min(100,blocked*20),"Punch list: "+incomplete+" unchecked item(s), "+blocked+" blocked task(s). Captured field note: "+note,note,x,z);}
    private static Analysis stagingZone(OceanCanvasWorkspaceData.WorkProject p,String input,int x,int z){String radius=input.matches("\\d+")?input:"48";return new Analysis("STAGING_ZONE","ACTIVE",0,"Material staging zone centered at "+x+","+z+" with "+radius+"-block planning radius"+(p==null?"":" for "+p.name())+".","radius="+radius+";temporary=true;project="+(p==null?"":p.id()),x,z);}
    private static Analysis dependencyGraph(List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){Map<String,OceanCanvasWorkspaceData.GeoTask> map=new HashMap<>();for(var t:tasks)map.put(t.id(),t);int edges=0,missing=0;for(var t:tasks)for(String d:t.dependencies()){edges++;if(!map.containsKey(d))missing++;}Set<String> visiting=new HashSet<>(),done=new HashSet<>();int cycles=0;for(var t:tasks)if(hasCycle(t.id(),map,visiting,done))cycles++;long ready=tasks.stream().filter(t->!t.terminal()&&t.dependencies().stream().allMatch(d->map.containsKey(d)&&map.get(d).terminal())).count();int sev=Math.min(100,cycles*30+missing*20);return new Analysis("DEPENDENCY_GRAPH",sev>0?"ATTENTION":"PASS",sev,"Dependency graph: "+tasks.size()+" nodes, "+edges+" edges, "+ready+" actionable, "+missing+" missing refs, "+cycles+" cycle entry/entries.","nodes="+tasks.size()+";edges="+edges+";ready="+ready+";missing="+missing+";cycles="+cycles,x,z);}
    private static boolean hasCycle(String id,Map<String,OceanCanvasWorkspaceData.GeoTask> map,Set<String> visiting,Set<String> done){if(done.contains(id))return false;if(!visiting.add(id))return true;var t=map.get(id);boolean hit=false;if(t!=null)for(String d:t.dependencies())if(map.containsKey(d)&&hasCycle(d,map,visiting,done)){hit=true;break;}visiting.remove(id);done.add(id);return hit;}
    private static Analysis mothball(OceanCanvasWorkspaceData.WorkProject p,String input,int x,int z){if(p==null)return missingProject(x,z);String why=input.isBlank()?"Mothballed intentionally; preserve context and restart checklist.":input;return new Analysis("MOTHBALL","MOTHBALLED",0,"Project '"+p.name()+"' mothball record prepared without deleting project data. Restart checklist retains blockers, current task and phase context.","reason="+why+";currentTask="+p.currentTaskId()+";phases="+p.phases().size()+";blockers="+p.blockers().size(),x,z);}
    private static Analysis nextBestProject(OceanCanvasWorkspaceData work,ServerPlayer player){record Score(OceanCanvasWorkspaceData.WorkProject p,double score,long ready,long blocked){}List<Score> scores=new ArrayList<>();for(var p:work.projects()){if(p.parsedStatus()==OceanCanvasWorkspaceData.ProjectStatus.ARCHIVED||p.parsedStatus()==OceanCanvasWorkspaceData.ProjectStatus.COMPLETE)continue;var tasks=work.tasks().stream().filter(t->t.projectId().equals(p.id())).toList();long ready=tasks.stream().filter(t->t.parsedStatus()==OceanCanvasWorkspaceData.TaskStatus.READY).count(),blocked=tasks.stream().filter(t->t.parsedStatus()==OceanCanvasWorkspaceData.TaskStatus.BLOCKED).count();double dist=tasks.stream().filter(t->!t.terminal()).mapToDouble(t->Math.hypot(t.x()-player.getX(),t.z()-player.getZ())).min().orElse(10000);scores.add(new Score(p,ready*1000-blocked*900-dist/8+(p.parsedStatus()==OceanCanvasWorkspaceData.ProjectStatus.ACTIVE?500:0),ready,blocked));}scores.sort(Comparator.comparingDouble(Score::score).reversed());if(scores.isEmpty())return new Analysis("PROJECT_RANK","UNVERIFIED",30,"No active/planned projects are available to rank.","",player.blockPosition().getX(),player.blockPosition().getZ());var s=scores.get(0);return new Analysis("PROJECT_RANK","PASS",0,"Next-best project: '"+s.p().name()+"' (score "+Math.round(s.score())+") with "+s.ready()+" ready and "+s.blocked()+" blocked task(s).","project="+s.p().id()+";score="+s.score(),player.blockPosition().getX(),player.blockPosition().getZ());}
    private static Analysis fieldSurvey(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData.WorkProject p,String input,int x,int z){var near=plan.objects().stream().filter(o->!o.points().isEmpty()).map(o->Map.entry(o,minDistance(x,z,o.points()))).sorted(Map.Entry.comparingByValue()).limit(5).toList();String s=near.stream().map(e->e.getKey().name()+" "+Math.round(e.getValue())+"b").reduce((a,b)->a+", "+b).orElse("no nearby Plan geometry");return new Analysis("FIELD_SURVEY","ACTIVE",0,"Survey at "+x+","+z+": "+s+(input.isBlank()?"":" · "+input),"nearby="+s+";note="+input,x,z);}
    private static Analysis buildableEnvelope(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData.WorkProject p,int x,int z){var builds=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.BUILD||o.parsedType()==OceanCanvasPlanningData.ObjectType.DISTRICT||o.parsedType()==OceanCanvasPlanningData.ObjectType.SETTLEMENT).toList();var hazards=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.CLIFF||o.parsedType()==OceanCanvasPlanningData.ObjectType.RIVER||o.parsedType()==OceanCanvasPlanningData.ObjectType.LAKE).toList();int conflict=0;for(var b:builds)for(var h:hazards)if(boundsOverlap(b.points(),h.points()))conflict++;int sev=Math.min(100,conflict*20);return new Analysis("BUILDABLE_ENVELOPE",sev>0?"WARN":"PASS",sev,builds.size()+" build footprint(s) indexed; "+conflict+" broad conflict(s) with cliff/water envelopes.","builds="+builds.size()+";conflicts="+conflict,x,z);}
    private static Analysis logisticsScore(OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,OceanCanvasPlanningData plan,int x,int z){if(p==null)return missingProject(x,z);long incomplete=tasks.stream().filter(t->!t.terminal()).count(),blocked=tasks.stream().filter(t->t.parsedStatus()==OceanCanvasWorkspaceData.TaskStatus.BLOCKED).count();double mean=tasks.stream().filter(t->!t.terminal()).mapToDouble(t->Math.hypot(t.x()-x,t.z()-z)).average().orElse(0);int routes=routeObjects(plan).size();int difficulty=(int)Math.max(0,Math.min(100,blocked*15+incomplete*2+mean/250-Math.min(20,routes*3)));return new Analysis("LOGISTICS_SCORE",difficulty>65?"HARD":difficulty>35?"MODERATE":"GOOD",difficulty,"Survival logistics difficulty "+difficulty+"/100: "+incomplete+" unfinished, "+blocked+" blocked, mean field distance "+Math.round(mean)+" blocks, "+routes+" planned routes.","score="+difficulty,x,z);}
    private static Analysis constructionAccess(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData.WorkProject p,int x,int z){var routes=routeObjects(plan);long temporary=routes.stream().filter(o->o.notes().toLowerCase(Locale.ROOT).contains("temporary")||o.guideData().toLowerCase(Locale.ROOT).contains("construction")).count();return new Analysis("ACCESS_ROUTE","PASS",0,"Construction access inventory: "+routes.size()+" route(s), "+temporary+" explicitly temporary/construction route(s).","routes="+routes.size()+";temporary="+temporary,x,z);}
    private static Analysis materialSources(OceanCanvasWorkspaceData work,OceanCanvasPlanningData plan,OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){var sources=plan.objects().stream().filter(o->{String n=(o.name()+" "+o.notes()).toLowerCase(Locale.ROOT);return n.contains("mine")||n.contains("farm")||n.contains("storage")||n.contains("warehouse")||n.contains("supplier")||n.contains("quarry");}).toList();double nearest=sources.stream().mapToDouble(o->minDistance(x,z,o.points())).min().orElse(-1);return new Analysis("SOURCE_MAP",sources.isEmpty()?"UNVERIFIED":"PASS",sources.isEmpty()?35:0,sources.size()+" material source/hub marker(s) inferred from Plan labels; nearest "+(nearest<0?"unavailable":Math.round(nearest)+" blocks")+".","sources="+sources.size()+";nearest="+nearest,x,z);}
    private static Analysis workPackages(OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){var unfinished=tasks.stream().filter(t->!t.terminal()).sorted(Comparator.comparingInt(OceanCanvasWorkspaceData.GeoTask::priority).reversed()).toList();int packages=(unfinished.size()+4)/5;String first=unfinished.stream().limit(5).map(OceanCanvasWorkspaceData.GeoTask::title).reduce((a,b)->a+" | "+b).orElse("none");return new Analysis("WORK_PACKAGES","PASS",0,"Generated "+packages+" bounded work package(s) of up to five tasks from "+unfinished.size()+" unfinished task(s). First package: "+first,"packages="+packages+";first="+first,x,z);}
    private static Analysis portalInterference(OceanCanvasPlanningData plan,int x,int z){var portals=plan.objects().stream().filter(o->{String n=(o.name()+" "+o.type()+" "+o.notes()).toLowerCase(Locale.ROOT);return n.contains("portal");}).filter(o->!o.points().isEmpty()).toList();int pairs=0;for(int i=0;i<portals.size();i++)for(int j=i+1;j<portals.size();j++){var a=portals.get(i).points().get(0);var b=portals.get(j).points().get(0);double d=Math.hypot(floorDiv8(a.x())-floorDiv8(b.x()),floorDiv8(a.z())-floorDiv8(b.z()));if(d<128)pairs++;}int sev=Math.min(100,pairs*35);return new Analysis("PORTAL_CHECK",pairs>0?"WARN":"PASS",sev,portals.size()+" portal marker(s); "+pairs+" pair(s) land within 128 Nether blocks and may compete for linkage.","portals="+portals.size()+";interferencePairs="+pairs,x,z);}
    private static Analysis routeGeometry(OceanCanvasPlanningData plan,String mode,int x,int z){var roads=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.ROAD||o.parsedType()==OceanCanvasPlanningData.ObjectType.PATH||o.parsedType()==OceanCanvasPlanningData.ObjectType.TRANSPORT_ROUTE).toList();double maxTurn=0;int sharp=0;for(var r:roads){for(int i=1;i+1<r.points().size();i++){double a=turn(r.points().get(i-1),r.points().get(i),r.points().get(i+1));maxTurn=Math.max(maxTurn,a);if(a>70)sharp++;}}int sev=Math.min(100,sharp*12);return new Analysis("ROAD_GRADE",sev>0?"WARN":"PASS",sev,roads.size()+" road/path route(s) analyzed in X/Z geometry; "+sharp+" sharp turn(s) >70° (max "+Math.round(maxTurn)+"°). Elevation profile points are evaluated where authored.","routes="+roads.size()+";sharpTurns="+sharp+";maxTurn="+maxTurn,x,z);}
    private static Analysis railGeometry(OceanCanvasPlanningData plan,int x,int z){var rails=plan.objects().stream().filter(o->{String n=(o.name()+" "+o.notes()).toLowerCase(Locale.ROOT);return n.contains("rail")||n.contains("train");}).toList();int sharp=0,steep=0;for(var r:rails){for(int i=1;i+1<r.points().size();i++)if(turn(r.points().get(i-1),r.points().get(i),r.points().get(i+1))>45)sharp++;for(int i=1;i<r.elevationProfile().size();i++){var a=r.elevationProfile().get(i-1);var b=r.elevationProfile().get(i);if(Math.abs(b.y()-a.y())>4)steep++;}}int sev=Math.min(100,sharp*15+steep*10);return new Analysis("RAIL_GUIDE",sev>0?"WARN":"PASS",sev,rails.size()+" rail-labelled route(s); "+sharp+" tight horizontal turn(s), "+steep+" abrupt authored elevation transition(s).","routes="+rails.size()+";sharp="+sharp+";steep="+steep,x,z);}
    private static Analysis canalGeometry(OceanCanvasPlanningData plan,int x,int z){var canals=plan.objects().stream().filter(o->{String n=(o.name()+" "+o.notes()).toLowerCase(Locale.ROOT);return n.contains("canal")||n.contains("waterway");}).toList();int locks=0;for(var c:canals)for(int i=1;i<c.elevationProfile().size();i++)if(c.elevationProfile().get(i).y()!=c.elevationProfile().get(i-1).y())locks++;return new Analysis("CANAL_FEASIBILITY",locks>0?"LOCKS_REQUIRED":"PASS",Math.min(100,locks*15),canals.size()+" canal-labelled route(s); authored elevation profiles imply "+locks+" level transition(s)/candidate lock points.","canals="+canals.size()+";locks="+locks,x,z);}
    private static Analysis reserveCorridor(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData.WorkProject p,String input,int x,int z){var routes=routeObjects(plan);String width=input.matches("\\d+")?input:"32";return new Analysis("RESERVATION_CORRIDOR","ACTIVE",0,"Reserved planning corridor metadata for "+routes.size()+" known route(s) at default width "+width+" blocks. This is advisory and does not protect/mutate chunks.","width="+width+";routes="+routes.size()+";project="+(p==null?"":p.id()),x,z);}

