    private static Analysis reserveSummary(ServerLevel world,String kind,int x,int z){var rs=OceanCanvasForeverWorldStewardshipData.get(world).reserves();long enabled=rs.stream().filter(OceanCanvasForeverWorldStewardshipData.Reserve::enabled).count();String versions=rs.stream().filter(OceanCanvasForeverWorldStewardshipData.Reserve::enabled).map(OceanCanvasForeverWorldStewardshipData.Reserve::expectedVersion).filter(v->!v.isBlank()).distinct().sorted().reduce((a,b)->a+","+b).orElse("unspecified");return new Analysis("RESERVE","PASS",0,kind+" reserve planner: "+enabled+" enabled reserve(s), expected versions "+versions+".","enabled="+enabled+";versions="+versions,x,z);}
    private static Analysis archiveSummary(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,int x,int z){var work=OceanCanvasWorkspaceData.get(world);var plan=OceanCanvasPlanningData.get(world);var prog=OceanCanvasProgramData.get(world);return new Analysis("ARCHIVE","PASS",0,"Archive set is portable/human-readable: "+work.projects().size()+" projects, "+work.tasks().size()+" tasks, "+plan.objects().size()+" Plan objects, "+prog.entries().size()+" P6-P10 artifacts; use existing project/package export for file emission.","project="+(p==null?"":p.id())+";projects="+work.projects().size()+";tasks="+work.tasks().size()+";plans="+plan.objects().size(),x,z);}
    private static Analysis historicalSnapshots(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,int x,int z){int region=OceanCanvasP1W3Data.get(world).snapshots().size();int pipeline=p==null?0:OceanCanvasPipelineSnapshotData.get(world).recent(p.id()).size();return new Analysis("HISTORY_SNAPSHOT","PASS",0,"Historical sparse snapshots available: "+region+" region/world snapshots and "+pipeline+" project pipeline snapshots.","regionSnapshots="+region+";pipelineSnapshots="+pipeline,x,z);}
    private static Analysis settlementCatchment(OceanCanvasPlanningData plan,int x,int z){var settlements=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.SETTLEMENT||o.parsedType()==OceanCanvasPlanningData.ObjectType.CITY).filter(o->!o.points().isEmpty()).toList();double mean=0;int pairs=0,overlap=0;for(int i=0;i<settlements.size();i++)for(int j=i+1;j<settlements.size();j++){double d=distance(first(settlements.get(i)),first(settlements.get(j)));mean+=d;pairs++;if(d<1600)overlap++;}if(pairs>0)mean/=pairs;return new Analysis("CATCHMENT",settlements.isEmpty()?"UNVERIFIED":"PASS",settlements.isEmpty()?30:0,settlements.size()+" settlement hub(s); "+overlap+" pair(s) within ~20-minute walking catchment (1600 blocks); mean inter-settlement distance "+Math.round(mean)+" blocks.","settlements="+settlements.size()+";overlapPairs="+overlap+";mean="+mean,x,z);}
    private static Analysis explorationPacing(OceanCanvasPlanningData plan,OceanCanvasP4PlanningData p4,int x,int z){var points=plan.objects().stream().filter(o->switch(o.parsedType()){case LANDMARK,SETTLEMENT,CITY,PORT,HARBOR->true;default->false;}).filter(o->!o.points().isEmpty()).map(OceanCanvasProgramService::first).toList();if(points.size()<2)return new Analysis("PACING","UNVERIFIED",25,"Need at least two landmark/settlement hubs to evaluate exploration pacing.","points="+points.size(),x,z);double sum=0;for(int i=1;i<points.size();i++)sum+=distance(points.get(i-1),points.get(i));double avg=sum/(points.size()-1);return new Analysis("PACING","PASS",0,"Exploration pacing index: "+points.size()+" major hubs, sequential mean spacing "+Math.round(avg)+" blocks (~"+Math.round(avg/80)+" walking minutes at 80 blocks/min heuristic).","hubs="+points.size()+";avgBlocks="+avg,x,z);}
