    private static Analysis geographicHierarchy(OceanCanvasPlanningData plan,String input,int x,int z){Map<String,Integer> types=new LinkedHashMap<>();for(var o:plan.objects())types.merge(o.parsedType().name(),1,Integer::sum);String spec=input.isBlank()?"CONTINENT > REALM > REGION > PROVINCE > LOCALITY > SITE":input;return new Analysis("GEO_HIERARCHY","ACTIVE",0,"Named geographic hierarchy recorded independently of Canvas protection regions. Plan inventory has "+types.size()+" semantic types.","hierarchy="+spec+";inventory="+types,x,z);}
    private static Analysis alternateNames(OceanCanvasPlanningData plan,String subject,String input,int x,int z){var o=subject.isBlank()?nearestObject(plan,x,z):plan.object(subject);String target=o==null?(subject.isBlank()?"place":subject):o.name();String aliases=input.isBlank()?target+"|local:unset|historic:unset|translation:unset":input;return new Analysis("ALT_NAMES","ACTIVE",0,"Alternate-name record for '"+target+"' created; names remain metadata and do not rename canonical Plan IDs.",aliases,x,z);}
    private static Analysis loreChronology(OceanCanvasProgramData prog,String input,int x,int z){String event=input.isBlank()?"World event at "+java.time.Instant.now():input;long existing=prog.featureEntries("OC-F187").size();return new Analysis("CHRONOLOGY","ACTIVE",0,"Lore chronology event #"+(existing+1)+" recorded with real timestamp and map coordinate.",event,x,z);}
