    private static Analysis placeDossier(ServerLevel world,OceanCanvasPlanningData plan,OceanCanvasWorkspaceData work,String subject,int x,int z){var o=subject.isBlank()?nearestObject(plan,x,z):plan.object(subject);String id=o==null?subject:o.id(),name=o==null?(subject.isBlank()?"nearest place":subject):o.name();long projects=work.projects().stream().filter(p->p.planningObjectIds().contains(id)).count(),tasks=work.tasks().stream().filter(t->t.planningObjectId().equals(id)).count();return new Analysis("DOSSIER","PASS",0,"Place dossier '"+name+"': "+projects+" linked project(s), "+tasks+" linked task(s), coordinate "+x+","+z+", plus available Atlas/history/program evidence.","place="+id+";projects="+projects+";tasks="+tasks,x,z);}
