    private static Analysis sharedNote(OceanCanvasWorkspaceData.WorkProject p,String input,ServerPlayer player,int x,int z){String note=input.isBlank()?"Shared field note at "+x+","+z:input;return new Analysis("SHARED_NOTE","OPEN",0,"Shared field note by "+player.getGameProfile().name()+" at "+x+","+z+(p==null?"":" for "+p.name())+": "+note,note,x,z);}
    private static Analysis reviewWorkflow(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,String subject,String input,ServerPlayer player,int x,int z){String target=!subject.isBlank()?subject:p==null?"":p.id();if(target.isBlank())return missingProject(x,z);String type=p!=null&&target.equals(p.id())?"PROJECT":"PLAN";try{var r=OceanCanvasP1W4Service.addReview(world,type,target,"P8 proposal review",player.getGameProfile().name(),input.isBlank()?"Review requested from P8 workbench.":input);return new Analysis("REVIEW","OPEN",0,"Review proposal "+r.id()+" opened for "+type.toLowerCase(Locale.ROOT)+" "+target+". Existing approval/changes-requested/reject workflow remains authoritative.","reviewId="+r.id(),x,z);}catch(IllegalArgumentException ex){return new Analysis("REVIEW","WARN",50,"Could not open review: "+ex.getMessage(),input,x,z);}}
    private static Analysis presence(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,int x,int z){var players=world.players();String names=players.stream().map(v->v.getGameProfile().name()+"@"+v.blockPosition().getX()+","+v.blockPosition().getZ()).reduce((a,b)->a+" | "+b).orElse("none");return new Analysis("PRESENCE","LIVE",0,"Opt-in project-map presence snapshot: "+players.size()+" player(s) in this dimension. "+names,"players="+names+";project="+(p==null?"":p.id()),x,z);}
    private static Analysis mapComment(OceanCanvasWorkspaceData.WorkProject p,String subject,String input,ServerPlayer player,int x,int z){String body=input.isBlank()?"Map comment":input;return new Analysis("MAP_COMMENT","OPEN",0,"Thread-root map comment by "+player.getGameProfile().name()+" at "+x+","+z+"; subject="+(subject.isBlank()?(p==null?"world":p.id()):subject)+".",body,x,z);}

    // ----- P9 helpers -----
    private static Analysis landformGrammar(OceanCanvasPlanningData plan,String subject,String input,int x,int z){String preset=input.isBlank()?"ARCHIPELAGO":upper(input);String guide=switch(preset){case "FJORD"->"deep narrow inlets + parallel ridges + limited cross-valleys";case "DELTA"->"distributary fan + wetlands + low relief + shifting channels";case "ATOLL"->"ring islands + lagoon + reef breaks + asymmetric passes";case "VOLCANIC_CHAIN"->"aligned peaks + age gradient + radial drainage";default->"primary silhouette + clustered secondary islands + scale-varied gaps";};return new Analysis("GRAMMAR","ADVISORY",0,"Landform grammar preset "+preset+": "+guide+". It creates guidance only; no terrain is generated.","preset="+preset+";guide="+guide+";subject="+subject,x,z);}
    private static Analysis silhouetteScore(OceanCanvasPlanningData plan,String subject,int x,int z){var objects=subject.isBlank()?plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.CONTINENT||o.parsedType()==OceanCanvasPlanningData.ObjectType.FREEFORM_AREA).toList():List.of(plan.object(subject)).stream().filter(java.util.Objects::nonNull).toList();if(objects.isEmpty())return new Analysis("SILHOUETTE","UNVERIFIED",30,"No continent/freeform closed shape selected.","",x,z);double score=0;int n=0;StringBuilder detail=new StringBuilder();for(var o:objects){if(o.points().size()<3)continue;double a=Math.abs(area(o.points())),p=perimeter(o.points());double compact=p<=0?0:4*Math.PI*a/(p*p);double turns=turnVariation(o.points());double s=Math.max(0,Math.min(100,35+45*(1-compact)+20*Math.min(1,turns/60)));score+=s;n++;if(detail.length()>0)detail.append(" | ");detail.append(o.name()).append('=').append(Math.round(s));}score=n==0?0:score/n;return new Analysis("SILHOUETTE",score<35?"FEATURELESS":score>88?"NOISY":"PASS",(int)Math.abs(score-62),"Silhouette recognizability heuristic "+Math.round(score)+"/100 across "+n+" shape(s): "+detail,"score="+score+";detail="+detail,x,z);}
    private static Analysis suggestionGhost(OceanCanvasPlanningData plan,String subject,int x,int z){var o=subject.isBlank()?nearestObject(plan,x,z):plan.object(subject);if(o==null||o.points().size()<2)return new Analysis("GHOST","UNVERIFIED",25,"Select a Plan line/area with at least two vertices.","",x,z);var pts=o.points();StringBuilder ghost=new StringBuilder();for(int i=1;i<pts.size()&&i<=24;i++){var a=pts.get(i-1);var b=pts.get(i);int mx=(a.x()+b.x())/2,mz=(a.z()+b.z())/2;int seed=(o.id().hashCode()*31+i*17);int dx=Math.floorMod(seed,65)-32,dz=Math.floorMod(seed/7,65)-32;if(ghost.length()>0)ghost.append(';');ghost.append(mx+dx).append(',').append(mz+dz);}return new Analysis("GHOST","ADVISORY",0,"Generated "+Math.min(24,pts.size()-1)+" deterministic suggestion-ghost control point(s) for '"+o.name()+"'. Nothing is accepted automatically.",ghost.toString(),x,z);}
    private static Analysis diegeticLayers(OceanCanvasWorkspaceData work,OceanCanvasProgramData prog,int x,int z){long rumors=prog.entries().stream().filter(e->e.payload().toUpperCase(Locale.ROOT).contains("RUMOR")).count(),canon=prog.entries().stream().filter(e->e.payload().toUpperCase(Locale.ROOT).contains("CANON")).count();return new Analysis("DIEGETIC_LAYERS","PASS",0,"Knowledge layers can separate "+work.atlasFeatures().size()+" Atlas markers plus "+rumors+" rumor and "+canon+" canon-tagged program artifacts into planned/surveyed/rumored/admin views.","atlas="+work.atlasFeatures().size()+";rumor="+rumors+";canon="+canon,x,z);}
    private static Analysis namingConsistency(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData work,OceanCanvasProgramData prog,int x,int z){Map<String,Integer> names=new HashMap<>();for(var o:plan.objects())names.merge(normName(o.name()),1,Integer::sum);for(var p:work.projects())names.merge(normName(p.name()),1,Integer::sum);for(var a:work.atlasFeatures())names.merge(normName(a.name()),1,Integer::sum);long dup=names.values().stream().filter(v->v>1).count();long numeric=names.keySet().stream().filter(v->v.matches(".*\\d{2,}.*")).count();int sev=(int)Math.min(100,dup*20+numeric*5);return new Analysis("NAMING",sev>0?"WARN":"PASS",sev,"Naming consistency scan: "+names.size()+" normalized names, "+dup+" duplicate normalized name(s), "+numeric+" placeholder-like numeric name(s).","names="+names.size()+";duplicates="+dup+";numeric="+numeric,x,z);}
    private static Analysis discoveryJournal(OceanCanvasWorkspaceData work,OceanCanvasWorkspaceData.WorkProject p,String input,int x,int z){String note=input.isBlank()?"Discovery at "+x+","+z:input;return new Analysis("DISCOVERY_JOURNAL","ACTIVE",0,"Discovery journal entry prepared at "+x+","+z+(p==null?"":" near "+p.name())+": "+note,note,x,z);}
    private static Analysis escrowSnapshot(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,int x,int z){var health=OceanCanvasWorldHealthScorecard.snapshot(world);var tickets=OceanCanvasTicketOwnershipInspector.snapshot(world,32);var gates=OceanCanvasWorkflowGateService.evaluate(world,"ESCROW_SNAPSHOT");String fp=sha256("project="+(p==null?"":p.id())+"|health="+health.components()+"|tickets="+tickets.total()+"|gates="+gates);return new Analysis("ESCROW","PASS",0,"Protected-area escrow metadata snapshot fingerprint "+fp.substring(0,16)+" captures project/health/ticket/gate state before destructive work; no terrain copied.","sha256="+fp+";project="+(p==null?"":p.id()),x,z);}
    private static Analysis declutterRules(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData work,int x,int z){Map<String,Long> ranks=new LinkedHashMap<>();ranks.put("atlas",plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.CONTINENT||o.parsedType()==OceanCanvasPlanningData.ObjectType.CITY).count());ranks.put("region",plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.REGION||o.parsedType()==OceanCanvasPlanningData.ObjectType.SETTLEMENT).count());ranks.put("local",(long)plan.objects().size()-ranks.values().stream().mapToLong(Long::longValue).sum());return new Analysis("DECLUTTER","PASS",0,"Semantic declutter tiers: atlas "+ranks.get("atlas")+", region "+ranks.get("region")+", local "+ranks.get("local")+"; selected/focused objects remain exempt.",ranks.toString(),x,z);}
    private static Analysis horizonPreview(OceanCanvasPlanningData plan,OceanCanvasWorkspaceData work,int x,int z){var peaks=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.PEAK||o.parsedType()==OceanCanvasPlanningData.ObjectType.MOUNTAIN_RANGE||o.parsedType()==OceanCanvasPlanningData.ObjectType.LANDMARK).filter(o->!o.points().isEmpty()).map(o->Map.entry(o,Math.atan2(first(o).z()-z,first(o).x()-x))).sorted(Map.Entry.comparingByValue()).limit(16).toList();String profile=peaks.stream().map(e->e.getKey().name()+"@"+Math.round(Math.toDegrees(e.getValue()))+"°").reduce((a,b)->a+" | "+b).orElse("no planned peaks/landmarks");return new Analysis("HORIZON","ADVISORY",0,"Simplified horizon profile from "+x+","+z+": "+profile+". Elevation uses authored profile/semantic intent where available; unknown heights stay advisory.",profile,x,z);}
    private static Analysis fractalDial(OceanCanvasPlanningData plan,String subject,String input,int x,int z){double dial=0.5;try{if(!input.isBlank())dial=Math.max(0,Math.min(1,Double.parseDouble(input)));}catch(Exception ignored){}var o=subject.isBlank()?nearestObject(plan,x,z):plan.object(subject);int pts=o==null?0:o.points().size();int target=(int)Math.round(pts*(0.5+dial*1.5));return new Analysis("FRACTAL_DIAL","ADVISORY",0,"Fractal detail dial "+String.format(Locale.ROOT,"%.2f",dial)+" suggests ~"+target+" control points from current "+pts+" while preserving the large-scale silhouette. No geometry is changed automatically.","dial="+dial+";current="+pts+";suggested="+target,x,z);}
    private static Analysis acceptanceCriteria(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,String input,int x,int z){if(p==null)return missingProject(x,z);long complete=tasks.stream().filter(OceanCanvasWorkspaceData.GeoTask::terminal).count();double pct=tasks.isEmpty()?0:complete*100.0/tasks.size();var verify=OceanCanvasP1W3Service.verifyProject(world,p.id());String criteria=input.isBlank()?"tasks>=90%;deviations=0;unverified=0":input;boolean pass=pct>=90&&verify.deviations()==0&&verify.unverified()==0;return new Analysis("ACCEPTANCE",pass?"PASS":"NOT_MET",pass?0:60,"World-linked criteria '"+criteria+"': task completion "+Math.round(pct)+"%, deviations "+verify.deviations()+", unverified "+verify.unverified()+".",criteria,x,z);}
    private static Analysis buildOrder(List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){Map<String,OceanCanvasWorkspaceData.GeoTask> map=new LinkedHashMap<>();for(var t:tasks)map.put(t.id(),t);List<String> order=new ArrayList<>();Set<String> done=new HashSet<>();boolean progress=true;while(progress){progress=false;for(var t:tasks)if(!t.terminal()&&!done.contains(t.id())&&t.dependencies().stream().allMatch(d->!map.containsKey(d)||map.get(d).terminal()||done.contains(d))){done.add(t.id());order.add(t.title());progress=true;}}int unresolved=(int)tasks.stream().filter(t->!t.terminal()&&!done.contains(t.id())).count();return new Analysis("BUILD_ORDER",unresolved>0?"WARN":"PASS",Math.min(100,unresolved*15),"Build-order simulator scheduled "+order.size()+" unfinished task(s); "+unresolved+" remain dependency-blocked/cyclic. First: "+order.stream().limit(8).reduce((a,b)->a+" → "+b).orElse("none"),"order="+String.join("|",order),x,z);}
    private static Analysis routeHierarchy(OceanCanvasPlanningData plan,int x,int z){Map<String,Integer> c=new LinkedHashMap<>();for(var o:routeObjects(plan)){String n=(o.name()+" "+o.notes()).toLowerCase(Locale.ROOT);String k=n.contains("royal")?"ROYAL_ROAD":n.contains("rail")?"RAIL":n.contains("sea")||n.contains("boat")?"SEA_LANE":n.contains("nether")||n.contains("portal")?"PORTAL_ROUTE":o.parsedType()==OceanCanvasPlanningData.ObjectType.PATH?"TRAIL":"LOCAL_ROAD";c.merge(k,1,Integer::sum);}return new Analysis("ROUTE_HIERARCHY","PASS",0,"Route hierarchy: "+c,c.toString(),x,z);}
    private static Analysis ecologicalCorridors(OceanCanvasPlanningData plan,OceanCanvasP4PlanningData p4,int x,int z){var habitats=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.FOREST||o.parsedType()==OceanCanvasPlanningData.ObjectType.BIOME_AREA).toList();var builds=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.BUILD||o.parsedType()==OceanCanvasPlanningData.ObjectType.DISTRICT).toList();int sever=0;for(var h:habitats)for(var b:builds)if(boundsOverlap(h.points(),b.points()))sever++;return new Analysis("ECO_CORRIDOR",sever>0?"WARN":"PASS",Math.min(100,sever*20),habitats.size()+" habitat area(s), "+sever+" broad project/build overlap(s) that may sever ecological continuity.","habitats="+habitats.size()+";sever="+sever,x,z);}
    private static Analysis resourceGeography(List<OceanCanvasWorkspaceData.GeoTask> tasks,OceanCanvasPlanningData plan,int x,int z){var demand=materialDemand(tasks,x,z);var sources=materialSources(null,plan,null,tasks,x,z);return new Analysis("RESOURCE_GEOGRAPHY",sources.state().equals("UNVERIFIED")?"UNVERIFIED":"PASS",sources.severity(),"Resource geography combines "+demand.summary()+" "+sources.summary(),demand.payload()+";"+sources.payload(),x,z);}
    private static Analysis stallScore(ServerLevel world,int x,int z){var s=OceanCanvasPerformanceEngine.summary(world);var tickets=OceanCanvasTicketOwnershipInspector.snapshot(world,64);double score=0;if("SATURATED".equals(s.io().state().name()))score+=30;if("STALLED".equals(s.io().state().name()))score+=55;if("REGRESSED".equals(s.baseline().state()))score+=25;if("SEVERE_DECAY".equals(s.decay().state()))score+=25;score+=Math.min(20,tickets.total()/5.0);score=Math.min(100,score);return new Analysis("STALL_SCORE",score>=70?"HIGH":score>=35?"ELEVATED":"LOW",(int)score,"Predictive stall score "+Math.round(score)+"/100 from I/O="+s.io().state()+", baseline="+s.baseline().state()+", decay="+s.decay().state()+", tickets="+tickets.total()+".","score="+score,x,z);}
    private static Analysis cleanupProof(ServerLevel world,int x,int z){var tickets=OceanCanvasTicketOwnershipInspector.snapshot(world,256);var health=OceanCanvasWorldHealthScorecard.snapshot(world);var owner=OceanCanvasOperationOwnership.snapshot(world);int sev=Math.min(100,tickets.total()*20+(owner.active()?50:0));return new Analysis("CLEANUP_PROOF",sev>0?"NOT_CLEAN":"PASS",sev,"Cleanup proof: "+tickets.summary()+" Operation ownership "+(owner.active()?"active":"idle")+"; health attention="+health.attentionCount()+".","tickets="+tickets.total()+";operationActive="+owner.active(),x,z);}
    private static Analysis performanceFingerprint(ServerLevel world,int x,int z){var s=OceanCanvasPerformanceEngine.summary(world);String raw=s.baseline().state()+"|"+s.decay().state()+"|"+s.io().state()+"|"+s.phases()+"|"+s.budgets();String fp=sha256(raw);return new Analysis("PERF_FINGERPRINT","PASS",0,"Performance baseline fingerprint "+fp.substring(0,16)+" (baseline "+s.baseline().state()+", decay "+s.decay().state()+", I/O "+s.io().state()+").",fp,x,z);}
    private static Analysis safeDefaults(int x,int z){var c=OceanCanvasConfig.get();List<String> diffs=new ArrayList<>();if(!c.pregenEnabled())diffs.add("Pregen disabled");if(c.pregenChunksPerTick()>64)diffs.add("pregenChunksPerTick > 64");if(c.oceanFloorVariation()>8)diffs.add("ocean floor variation > 8");if(!c.biomeMaskEnabled())diffs.add("biome mask disabled");int sev=Math.min(100,diffs.size()*20);return new Analysis("SAFE_DEFAULTS",diffs.isEmpty()?"PASS":"REVIEW",sev,"Safe-default audit found "+diffs.size()+" notable difference(s): "+(diffs.isEmpty()?"none":String.join("; ",diffs))+". No settings were changed.",String.join("|",diffs),x,z);}
    private static Analysis rainShadow(OceanCanvasPlanningData plan,String input,int x,int z){var ridges=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.MOUNTAIN_RANGE||o.parsedType()==OceanCanvasPlanningData.ObjectType.RIDGELINE).toList();String wind=input.isBlank()?"WEST_TO_EAST":upper(input);return new Analysis("RAIN_SHADOW","ADVISORY",0,"Rain-shadow guide uses "+ridges.size()+" mountain/ridgeline object(s) with prevailing wind "+wind+"; leeward sides are advisory only and do not modify biome/weather systems.","ridges="+ridges.size()+";wind="+wind,x,z);}
    private static Analysis bridgeFinder(OceanCanvasPlanningData plan,int x,int z){var rivers=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.RIVER).toList();var roads=plan.objects().stream().filter(o->o.parsedType()==OceanCanvasPlanningData.ObjectType.ROAD||o.parsedType()==OceanCanvasPlanningData.ObjectType.PATH||o.parsedType()==OceanCanvasPlanningData.ObjectType.TRANSPORT_ROUTE).toList();int candidates=0;StringBuilder pts=new StringBuilder();for(var r:rivers)for(var road:roads)for(var a:r.points())if(minDistance(a.x(),a.z(),road.points())<48){candidates++;if(pts.length()<300){if(pts.length()>0)pts.append(';');pts.append(a.x()).append(',').append(a.z());}break;}return new Analysis("BRIDGE_FINDER",candidates>0?"PASS":"UNVERIFIED",0,"Found "+candidates+" route/river proximity candidate(s) within 48 blocks for bridge review.",pts.toString(),x,z);}
    private static Analysis physicalCompletion(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,List<OceanCanvasWorkspaceData.GeoTask> tasks,int x,int z){if(p==null)return missingProject(x,z);long complete=tasks.stream().filter(OceanCanvasWorkspaceData.GeoTask::terminal).count();double taskPct=tasks.isEmpty()?0:complete*100.0/tasks.size();var v=OceanCanvasP1W3Service.verifyProject(world,p.id());double physical=Math.max(0,100-v.deviations()*10-v.unverified()*3);double blended=tasks.isEmpty()?physical:taskPct*.45+physical*.55;return new Analysis("PHYSICAL_PROGRESS",v.unverified()>0?"UNVERIFIED":"PASS",Math.min(100,v.deviations()*15+v.unverified()*5),"Physical completion estimate "+Math.round(blended)+"% (task state "+Math.round(taskPct)+"%, verification component "+Math.round(physical)+"%; deviations="+v.deviations()+", unverified="+v.unverified()+").","completion="+blended,x,z);}
    private static Analysis multimodalRoutes(OceanCanvasPlanningData plan,int x,int z){Map<String,Long> modes=new LinkedHashMap<>();for(var o:routeObjects(plan)){String n=(o.name()+" "+o.notes()).toLowerCase(Locale.ROOT);String m=n.contains("rail")?"RAIL":n.contains("nether")||n.contains("portal")?"NETHER":n.contains("ice")?"ICE":n.contains("boat")||n.contains("sea")||n.contains("canal")?"BOAT":n.contains("elytra")?"ELYTRA":"WALK/ROAD";modes.merge(m,1L,Long::sum);}return new Analysis("MULTIMODAL","PASS",0,"Multimodal route inventory: "+modes+". Planner preserves mode boundaries so travel estimates can use mode-specific speeds.",modes.toString(),x,z);}
    private static Analysis isochrones(String input,int x,int z){int minutes=20;try{if(!input.isBlank())minutes=Math.max(1,Math.min(240,Integer.parseInt(input.replaceAll("[^0-9]",""))));}catch(Exception ignored){}int walk=minutes*80,boat=minutes*140,rail=minutes*320,nether=minutes*640;return new Analysis("ISOCHRONE","PASS",0,minutes+"-minute heuristic reach from "+x+","+z+": walk "+walk+"b, boat "+boat+"b, rail "+rail+"b, Nether-equivalent Overworld "+nether+"b.","minutes="+minutes+";walk="+walk+";boat="+boat+";rail="+rail+";nether="+nether,x,z);}
    private static Analysis incidentBundle(ServerLevel world,int x,int z){try{var r=OceanCanvasDiagnosticBundle.create(world);return new Analysis("INCIDENT_BUNDLE","PASS",0,"Incident bundle "+r.supportCode()+" created at "+r.file()+" ("+r.bytes()+" bytes).","file="+r.file()+";supportCode="+r.supportCode(),x,z);}catch(Exception ex){return new Analysis("INCIDENT_BUNDLE","FAIL",90,"Incident bundle creation failed: "+ex.getMessage(),"error="+ex.getMessage(),x,z);}}
    private static Analysis healthTrend(ServerLevel world,OceanCanvasProgramData prog,int x,int z){var s=OceanCanvasPerformanceEngine.summary(world);double now=healthMetric(s);var prev=prog.featureEntries("OC-F205").stream().max(Comparator.comparingLong(OceanCanvasProgramData.Entry::updatedAt)).orElse(null);double old=prev==null?Double.NaN:metric(prev.payload(),"metric");double delta=Double.isFinite(old)?now-old:0;int sev=Double.isFinite(old)&&delta>20?(int)Math.min(100,delta):0;return new Analysis("HEALTH_BASELINE",sev>0?"DEGRADED":"PASS",sev,"Health trend metric "+String.format(Locale.ROOT,"%.1f",now)+(Double.isFinite(old)?" vs baseline "+String.format(Locale.ROOT,"%.1f",old)+" (Δ "+String.format(Locale.ROOT,"%+.1f",delta)+")":"; first baseline sample"),"metric="+now+";baseline="+(Double.isFinite(old)?old:"none"),x,z);}
    private static double healthMetric(OceanCanvasPerformanceEngine.Summary s){double v=0;if(!"CLEAR".equals(s.io().state().name()))v+=25;if("REGRESSED".equals(s.baseline().state()))v+=35;if("DEGRADED".equals(s.baseline().state()))v+=20;if("SEVERE_DECAY".equals(s.decay().state()))v+=30;v+=s.budgets().stream().filter(b->"FAIL".equals(b.state())).count()*10;return Math.min(100,v);}
    private static Analysis canaryPhase(ServerLevel world,OceanCanvasWorkspaceData.WorkProject p,int x,int z){var latest=OceanCanvasBoundaryCanaryData.get(world).latestResult();String state=latest==null?"UNVERIFIED":latest.state();String detail=latest==null?"No boundary canary result exists yet; the canary phase is opt-in and must run before the full mutation operation.":latest.detail();return new Analysis("CANARY_PHASE",state,"FAIL".equals(state)?90:"UNVERIFIED".equals(state)?35:0,"Canary phase evidence: "+detail,"state="+state+";project="+(p==null?"":p.id()),x,z);}
    private static Analysis recoverySimulation(ServerLevel world,int x,int z){var gates=OceanCanvasWorkflowGateService.evaluate(world,"RECOVERY_SIMULATION");var tickets=OceanCanvasTicketOwnershipInspector.snapshot(world,64);var owner=OceanCanvasOperationOwnership.snapshot(world);int sev=owner.active()?50:0;return new Analysis("RECOVERY_SIM","SIMULATED",sev,"Recovery simulation: operationOwner="+(owner.active()?"active":"idle")+", tickets="+tickets.total()+", workflow gates="+(gates.pass()?"PASS":"BLOCKED")+". No recovery action was applied.","ownerActive="+owner.active()+";tickets="+tickets.total()+";gates="+gates.summary(),x,z);}
